import type { MapGridConfig } from '../types';
import type { MapDocument } from '../shared/spatial/types.ts';
import { mapDocumentToGridConfig } from '../shared/spatial/adapter.ts';

interface MapIndex {
  schemaVersion: number;
  maps: Record<string, { title: string; file: string; kind: string }>;
  byImage: Record<string, string>;
}

const INDEX_URL = '/data/maps/index.json';
const DOC_BASE = '/data/maps/';

/**
 * Loads compiled MapDocuments (public/data/maps/) and answers by image URL.
 * These are generated by tools/maps/build_maps.py and are read-only here.
 */
class MapDataService {
  private index: MapIndex | null = null;
  private indexPromise: Promise<MapIndex | null> | null = null;
  private docPromises = new Map<string, Promise<MapDocument | null>>();
  private gridCache = new Map<string, MapGridConfig>();

  private loadIndex(): Promise<MapIndex | null> {
    if (this.index) return Promise.resolve(this.index);
    if (!this.indexPromise) {
      this.indexPromise = (async () => {
        try {
          const res = await fetch(INDEX_URL);
          if (!res.ok) {
            this.indexPromise = null; // try again next time (for example after the maps are built)
            return null;
          }
          this.index = (await res.json()) as MapIndex;
          return this.index;
        } catch {
          this.indexPromise = null;
          return null;
        }
      })();
    }
    return this.indexPromise;
  }

  /** Same aliasing rule as MapGridService: only bundled /maps/ images match by basename. */
  private candidateKeys(url: string): string[] {
    const cleaned = url.split('?')[0];
    const basename = cleaned.split('/').pop();
    const keys = [url, cleaned];
    const isBundled = !cleaned.includes('/') || cleaned.endsWith(`/maps/${basename}`);
    if (basename && isBundled) keys.push(`/maps/${basename}`);
    return Array.from(new Set(keys));
  }

  public async getMapIdForUrl(url?: string): Promise<string | null> {
    if (!url) return null;
    const index = await this.loadIndex();
    if (!index) return null;
    for (const k of this.candidateKeys(url)) {
      if (index.byImage[k]) return index.byImage[k];
    }
    return null;
  }

  public async getDocumentById(mapId: string): Promise<MapDocument | null> {
    const pending = this.docPromises.get(mapId);
    if (pending) return pending;
    const p = (async () => {
      const index = await this.loadIndex();
      const entry = index?.maps[mapId];
      if (!entry) {
        this.docPromises.delete(mapId);
        return null;
      }
      try {
        const res = await fetch(DOC_BASE + entry.file);
        if (!res.ok) {
          this.docPromises.delete(mapId);
          return null;
        }
        return (await res.json()) as MapDocument;
      } catch {
        this.docPromises.delete(mapId);
        return null;
      }
    })();
    this.docPromises.set(mapId, p);
    return p;
  }

  public async getDocumentForUrl(url?: string): Promise<MapDocument | null> {
    const id = await this.getMapIdForUrl(url);
    return id ? this.getDocumentById(id) : null;
  }

  /** Grid config for an image URL in the legacy shape the UI already understands. */
  public async getGridForUrl(url?: string): Promise<MapGridConfig | null> {
    if (!url) return null;
    const doc = await this.getDocumentForUrl(url);
    // Overview maps carry no tactical grid; the existing detection path keeps handling them.
    if (!doc || doc.kind !== 'tactical') return null;
    const key = `${doc.mapId}|${url}`;
    let cfg = this.gridCache.get(key);
    if (!cfg) {
      cfg = mapDocumentToGridConfig(doc, url);
      this.gridCache.set(key, cfg);
    }
    return cfg;
  }

  /** Synchronous lookup, only useful after the document has been loaded once. */
  public getCachedGridForUrl(url?: string): MapGridConfig | null {
    if (!url) return null;
    const wanted = this.candidateKeys(url);
    for (const [key, cfg] of this.gridCache) {
      if (wanted.some((k) => key.endsWith(`|${k}`))) return cfg;
    }
    return null;
  }
}

export const mapDataService = new MapDataService();
